// ═══ STRUCTURED CONCURRENCY (preview — Java 21-25) ═══
// --enable-preview required!

// ShutdownOnFailure: if ANY subtask fails → cancel all siblings
record TransferResult(BigDecimal balance, boolean fraudClear, boolean compliant) {}

TransferResult verifyTransfer(String accountId) throws Exception {
    try (var scope = new StructuredTaskScope.ShutdownOnFailure()) {
        // Fork 3 subtasks — all run concurrently on virtual threads
        Subtask<BigDecimal> balanceTask = scope.fork(() -> checkBalance(accountId));
        Subtask<Boolean> fraudTask = scope.fork(() -> checkFraud(accountId));
        Subtask<Boolean> complianceTask = scope.fork(() -> checkCompliance(accountId));

        scope.join();            // wait for ALL subtasks to complete
        scope.throwIfFailed();   // propagate first failure as exception

        // All succeeded — collect results
        return new TransferResult(
            balanceTask.get(), fraudTask.get(), complianceTask.get());
    }
    // If fraudTask fails → balanceTask and complianceTask are CANCELLED automatically!
    // No orphaned tasks. No resource leaks. Errors propagated.
}

// ShutdownOnSuccess: return first successful result, cancel rest
String fetchFromFastestMirror(String tradeId) throws Exception {
    try (var scope = new StructuredTaskScope.ShutdownOnSuccess<String>()) {
        scope.fork(() -> fetchFromMirror1(tradeId));
        scope.fork(() -> fetchFromMirror2(tradeId));
        scope.fork(() -> fetchFromMirror3(tradeId));

        scope.join();
        return scope.result();  // first successful result — others cancelled!
    }
}
