package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.concurrent.Callable;
import static org.assertj.core.api.Assertions.assertThat;

class StructuredConcurrencyTest {

    // Illustrative fan-out/fan-in using an executor to mimic scope semantics.
    String fraudCheck()   { return "FRAUD_OK"; }
    String balanceCheck() { return "BALANCE_OK"; }

    String transfer() throws Exception {
        try (var scope = new java.util.concurrent.StructuredTaskScope.ShutdownOnFailure()) {
            var f = scope.fork((Callable<String>) this::fraudCheck);
            var b = scope.fork((Callable<String>) this::balanceCheck);
            scope.join();                 // wait for both
            scope.throwIfFailed();        // propagate if either failed
            return f.get() + "+" + b.get();
        }
    }

    @Test
    void bothSubtasksAsOneUnit() throws Exception {
        assertThat(transfer()).isEqualTo("FRAUD_OK+BALANCE_OK");
    }
}
