sections.s5b_flow:
```
  ═══ UNSTRUCTURED (raw ExecutorService) ═══

  executor.submit(balanceCheck);     → runs independently
  executor.submit(fraudCheck);       → runs independently
  executor.submit(complianceCheck);  → runs independently
  // If fraudCheck fails:
  //   balanceCheck and complianceCheck KEEP RUNNING (orphaned!)
  //   Error handling scattered across 3 Future.get() calls

  ═══ STRUCTURED (StructuredTaskScope) ═══

  try (var scope = ShutdownOnFailure()) {
      scope.fork(balanceCheck);        → subtask
      scope.fork(fraudCheck);          → subtask
      scope.fork(complianceCheck);     → subtask
      scope.join();                    → wait for all
      scope.throwIfFailed();           → propagate first failure
  }
  // If fraudCheck fails:
  //   balanceCheck and complianceCheck CANCELLED automatically!
  //   ONE exception propagated to parent. No orphans. No leaks.
```
